 w.AudioWorkletNode=class{constructor(){node=this;this.port={close(){},postMessage:m=>{if(m?.type==='start'){this.frame=m.atFrame;setImmediate(()=>this.port.onmessage({data:{type:'armed'}}))}if(m==='stop')this.port.onmessage({data:{type:'stopped',frames:this.frames||0,sampleRate:8000}})}}}connect(){}disconnect(){}};
