 return {timing,complete(){node.port.onmessage({data:{type:'started',atFrame:node.frame}});node.frames=800;node.port.onmessage({data:{type:'pcm',samples:new Float32Array(800).fill(.25)}});node.port.onmessage({data:{type:'stopped',frames:800,sampleRate:8000}})},get node(){return node}};
